<?php
declare(strict_types=1);
namespace TempNumber;
putenv('DB_DSN=sqlite::memory:');putenv('APP_ENV=testing');putenv('TEXTVERIFIED_API_KEY=');putenv('TEXTVERIFIED_API_USERNAME=');
require __DIR__.'/../src/bootstrap.php';foreach(['Wallet','Pricing','Providers','Rentals','Payments','Rewards','Commerce','Reconciliation']as$f)require __DIR__.'/../src/'.$f.'.php';
foreach(glob(__DIR__.'/../migrations/*.sql')as$f)db()->exec(file_get_contents($f));
$passed=0;$failed=0;
function test(string $name,callable $fn):void {global $passed,$failed;try{$fn();$passed++;echo "PASS $name\n";}catch(\Throwable $e){$failed++;echo 'FAIL '.$name.': '.$e->getMessage()."\n";}}
function eq(mixed $a,mixed $b):void {if($a!==$b)throw new \RuntimeException(var_export($a,true).' !== '.var_export($b,true));}
function rejects(callable $fn,string $code):void {try{$fn();}catch(Problem $e){eq($e->key,$code);return;}throw new \RuntimeException('Expected '.$code);}
function customer(string $email):array {$uid=id();query('INSERT INTO users (id,name,email,password_hash,referral_code,created_at) VALUES (?,?,?,?,?,?)',[$uid,'Test',$email,password_hash('long-test-password',PASSWORD_DEFAULT),substr(id(),0,10),now()]);query('INSERT INTO wallets (user_id) VALUES (?)',[$uid]);return one('SELECT * FROM users WHERE id=?',[$uid]);}
function seedOrder(array $u,string $state='active',string $source='getatext',?string $sms=null):string {$id=id();query('INSERT INTO orders (id,user_id,provider,provider_order_id,product,service,status,sms_code,price_cents,price_tier,idempotency_key,request_hash,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[$id,$u['id'],$source,id(),$source==='5sim'?'global':'usa','test',$state,$sms,100,'retail',id(),hash('sha256','test'),now(),now()]);return $id;}
test('USD parses to exact cents',fn()=>eq(cents('10.09'),1009));
test('Money keeps two decimal places',fn()=>eq(money(9),'0.09'));
test('Floating point input rejected',fn()=>rejects(fn()=>cents(1.25),'INVALID_AMOUNT'));
test('Scientific notation rejected',fn()=>rejects(fn()=>cents('1e3'),'INVALID_AMOUNT'));
test('Negative amount rejected',fn()=>rejects(fn()=>cents('-1.00'),'INVALID_AMOUNT'));
test('Extra precision rejected',fn()=>rejects(fn()=>cents('1.001'),'INVALID_AMOUNT'));
$u=customer('wallet@test.invalid');
test('Verified top-up credits once',function()use($u){$id=id();query('INSERT INTO payments (id,user_id,provider,amount_cents,currency,status,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?)',[$id,$u['id'],'stripe',1000,'USD','pending',now(),now()]);$s=['id'=>'cs_'.$id,'metadata'=>['payment_id'=>$id,'user_id'=>$u['id']],'client_reference_id'=>$id,'currency'=>'usd','amount_total'=>1000,'payment_status'=>'paid'];Payments::credit($id,$s);Payments::credit($id,$s);eq(Wallet::balance($u['id'])['balance_usd'],'10.00');eq((int)one('SELECT COUNT(*) n FROM ledger WHERE user_id=?',[$u['id']])['n'],1);});
test('Payment mismatch never credits',function()use($u){$id=id();query('INSERT INTO payments (id,user_id,provider,amount_cents,currency,status,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?)',[$id,$u['id'],'stripe',100,'USD','pending',now(),now()]);rejects(fn()=>Payments::credit($id,['id'=>'bad','metadata'=>['payment_id'=>$id,'user_id'=>$u['id']],'client_reference_id'=>$id,'currency'=>'eur','amount_total'=>100,'payment_status'=>'paid']),'PAYMENT_MISMATCH');eq(Wallet::balance($u['id'])['balance_usd'],'10.00');});
test('Reservation reduces available balance without spending it',function()use($u){tx(fn()=>Wallet::change($u['id'],'reservation',0,'test:reserve','Test',900));eq(Wallet::balance($u['id'])['balance_usd'],'1.00');eq(Wallet::balance($u['id'])['reserved_usd'],'9.00');});
test('Overspending reserved balance is rejected',function()use($u){rejects(fn()=>tx(fn()=>Wallet::change($u['id'],'purchase',-101,'test:overspend','Test')),'INSUFFICIENT_FUNDS');eq(Wallet::balance($u['id'])['balance_usd'],'1.00');});
test('Reservation replay is idempotent',function()use($u){tx(fn()=>Wallet::change($u['id'],'reservation',0,'test:reserve','Test',900));eq(Wallet::balance($u['id'])['reserved_usd'],'9.00');});
test('Capture clears reservation exactly once',function()use($u){tx(fn()=>Wallet::change($u['id'],'purchase',-900,'test:capture','Test',-900));tx(fn()=>Wallet::change($u['id'],'purchase',-900,'test:capture','Test',-900));eq(Wallet::balance($u['id'])['balance_usd'],'1.00');eq(Wallet::balance($u['id'])['reserved_usd'],'0.00');});
test('Transaction rollback keeps ledger and balance consistent',function()use($u){try{tx(function()use($u){Wallet::change($u['id'],'bonus',300,'test:rollback','Test');throw new \RuntimeException('rollback');});}catch(\RuntimeException){}eq(Wallet::balance($u['id'])['balance_usd'],'1.00');eq(one('SELECT id FROM ledger WHERE reference=?',['test:rollback']),null);});
$r=customer('rentals@test.invalid');
test('Leading zero SMS code survives completion',function()use($r){$o=seedOrder($r);$res=Rentals::settle($o,['status'=>'received','sms_code'=>'001234']);eq($res['sms_code'],'001234');eq($res['status'],'completed');});
test('Received without code remains active',function()use($r){$o=seedOrder($r,'active','5sim');eq(Rentals::settle($o,['status'=>'received'])['status'],'active');});
test('Unconfirmed expiry cannot refund',function()use($r){$o=seedOrder($r);rejects(fn()=>Rentals::settle($o,['status'=>'expired']),'UNCONFIRMED_OUTCOME');eq(Rentals::owned($o,$r['id'])['status'],'active');});
test('Confirmed no-SMS refund happens once',function()use($r){$o=seedOrder($r);$result=['status'=>'cancelled','authoritative'=>true,'no_sms_confirmed'=>true];Rentals::settle($o,$result);Rentals::settle($o,$result);eq(Wallet::balance($r['id'])['balance_usd'],'1.00');});
test('SMS completion prevents a later cancellation refund',function()use($r){$o=seedOrder($r);Rentals::settle($o,['status'=>'received','sms_code'=>'000001']);$before=Wallet::balance($r['id']);Rentals::settle($o,['status'=>'cancelled','authoritative'=>true,'no_sms_confirmed'=>true]);eq(Wallet::balance($r['id']),$before);});
test('Rental ownership enforced',function()use($u,$r){$o=seedOrder($r);rejects(fn()=>Rentals::owned($o,$u['id']),'NOT_FOUND');});
test('Provider outage never refunds',function()use($r){$o=seedOrder($r);$before=Wallet::balance($r['id']);rejects(fn()=>Rentals::sync(Rentals::owned($o,$r['id'])),'PROVIDER_UNAVAILABLE');eq(Wallet::balance($r['id']),$before);eq(Rentals::owned($o,$r['id'])['status'],'active');});
test('Unavailable purchase never reserves funds',function()use($u){$before=Wallet::balance($u['id']);rejects(fn()=>Rentals::purchase($u,['service'=>'test'],id()),'PROVIDER_UNAVAILABLE');eq(Wallet::balance($u['id']),$before);});
test('Purchase replay returns existing intent without provider call',function()use($u){$key=id();$normal=['service'=>'test','catalogue'=>'usa','country'=>'usa','max_price_cents'=>null,'options'=>[],'tier'=>'wholesale'];$hash=hash('sha256',json_encode($normal,JSON_THROW_ON_ERROR));$o=seedOrder($u,'reconciliation');query('UPDATE orders SET idempotency_key=?,request_hash=? WHERE id=?',[$key,$hash,$o]);$res=Rentals::purchase($u,['service'=>'test'],$key,true);eq($res['id'],$o);eq($res['status'],'reconciliation');rejects(fn()=>Rentals::purchase($u,['service'=>'different'],$key,true),'IDEMPOTENCY_CONFLICT');});
test('Retail and wholesale margins are separate',function(){$c=['currency'=>'USD','fx_numerator'=>4,'fx_denominator'=>5,'fx_updated_at'=>now(),'retail_margin_cents'=>30,'wholesale_margin_cents'=>10];eq(Pricing::quote(100,$c),110);eq(Pricing::quote(100,$c,'wholesale'),90);});
test('Stale exchange rate blocks purchase',function(){$c=['currency'=>'USD','fx_numerator'=>1,'fx_denominator'=>1,'fx_updated_at'=>'2020-01-01','retail_margin_cents'=>1];rejects(fn()=>Pricing::quote(100,$c),'PRICING_STALE');});
test('Rounding uses integer ceilings',function(){$c=['currency'=>'USD','fx_numerator'=>1,'fx_denominator'=>3,'fx_updated_at'=>now(),'retail_margin_cents'=>1,'rounding_cents'=>5];eq(Pricing::quote(100,$c),35);});
test('Unconfigured public pricing is honest',fn()=>eq(Pricing::snapshot('usa','usa')['state'],'unavailable'));
test('London summer month starts in previous UTC day',function(){[$period,$start,$end]=Rewards::period(new \DateTimeImmutable('2026-07-15T12:00:00Z'));eq($period,'2026-07');eq($start,'2026-06-30 23:00:00');});
test('London winter month starts at UTC midnight',function(){[, $start]=Rewards::period(new \DateTimeImmutable('2026-12-15T12:00:00Z'));eq($start,'2026-12-01 00:00:00');});
test('October reward period accounts for DST change',function(){[, $start,$end]=Rewards::period(new \DateTimeImmutable('2026-10-15T12:00:00Z'));eq($start,'2026-09-30 23:00:00');eq($end,'2026-11-01 00:00:00');});
test('Paused rewards cannot be claimed',function()use($u){$row=one("SELECT value FROM settings WHERE name='rewards_v3'");$c=json_decode($row['value'],true);$c['enabled']=false;query("UPDATE settings SET value=? WHERE name='rewards_v3'",[json_encode($c)]);rejects(fn()=>Rewards::claim($u,'cashback'),'REWARDS_UNCONFIGURED');$c['enabled']=true;query("UPDATE settings SET value=? WHERE name='rewards_v3'",[json_encode($c)]);});
test('Reward claims are unique and auditable',function()use($u){$o=seedOrder($u,'completed');query('UPDATE orders SET price_cents=10000 WHERE id=?',[$o]);tx(function()use($u,$o){Wallet::change($u['id'],'topup',10000,'reward-test-funding','Test funds');Wallet::change($u['id'],'purchase',-10000,'purchase:'.$o,'Test charge');});RewardAccounting::record($o,$u['id'],$o,'usa','purchase:'.$o,['cost_minor'=>5000],['fx_numerator'=>1,'fx_denominator'=>1]);query("UPDATE reward_costs SET created_at='2020-01-01 00:00:00',settled_at='2020-01-01 00:00:00' WHERE source_id=?",[$o]);Rewards::claim($u,'cashback');rejects(fn()=>Rewards::claim($u,'cashback'),'REWARD_INELIGIBLE');eq((int)one('SELECT COUNT(*) n FROM reward_claims WHERE user_id=?',[$u['id']])['n'],1);});
test('SMM negative quantities rejected before provider',fn()=>rejects(fn()=>Commerce::fulfil($u,'smm','purchase',['target'=>'https://example.com','quantity'=>-1],id()),'INVALID_QUANTITY'));
test('SMM unsafe link schemes rejected',fn()=>rejects(fn()=>Commerce::fulfil($u,'smm','purchase',['target'=>'javascript:alert(1)','quantity'=>10],id()),'INVALID_TARGET'));
test('Inbox ownership checked on every request',fn()=>rejects(fn()=>Commerce::owned('temp-mail',id(),$u['id']),'NOT_FOUND'));
test('Key rotation preserves account order ownership',function()use($u){$o=seedOrder($u);$old=id();query('INSERT INTO api_keys (id,user_id,key_hash,prefix,created_at) VALUES (?,?,?,?,?)',[$old,$u['id'],hash('sha256','old'),'old',now()]);query('UPDATE api_keys SET revoked_at=? WHERE id=?',[now(),$old]);query('INSERT INTO api_keys (id,user_id,key_hash,prefix,created_at) VALUES (?,?,?,?,?)',[id(),$u['id'],hash('sha256','new'),'new',now()]);eq(Rentals::owned($o,$u['id'])['user_id'],$u['id']);eq(one('SELECT id FROM api_keys WHERE key_hash=? AND revoked_at IS NULL',[hash('sha256','old')]),null);});
test('Forged Stripe signature rejected',function(){putenv('STRIPE_WEBHOOK_SECRET=test-only-not-a-real-secret');rejects(fn()=>StripeCheckout::webhook('{}','t='.time().',v1=fake'),'INVALID_SIGNATURE');});
test('Expired Stripe signature rejected',function(){$raw='{}';$time=time()-301;$sig=hash_hmac('sha256',$time.'.'.$raw,env('STRIPE_WEBHOOK_SECRET'));rejects(fn()=>StripeCheckout::webhook($raw,'t='.$time.',v1='.$sig),'INVALID_SIGNATURE');});
test('Valid Stripe signature accepted',function(){$raw='{"type":"test"}';$time=time();$sig=hash_hmac('sha256',$time.'.'.$raw,env('STRIPE_WEBHOOK_SECRET'));eq(StripeCheckout::webhook($raw,'t='.$time.',v1='.$sig)['type'],'test');});
function commerceIntent(array $u,string $product,array $input,?string $resource=null):string {$id=id();tx(function()use($u,$product,$input,$resource,$id){Wallet::change($u['id'],'topup',1000,'seed:'.$id,'Test funds');Wallet::change($u['id'],'reservation',0,'commerce-reserve:'.$id,'Test reservation',100);query('INSERT INTO fulfilment_intents (id,user_id,product,operation,resource_id,request_hash,idempotency_key,price_cents,status,request_payload,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)',[$id,$u['id'],$product,$resource?'renewal':'purchase',$resource,hash('sha256',json_encode($input)),id(),100,'reconciliation',json_encode($input),now(),now()]);});return $id;}
test('Provisioned inbox survives local activation failure and recovers once',function(){ $c=customer('inbox-recovery@test.invalid');$i=commerceIntent($c,'temp-mail',[]);try{Commerce::activate($i,['id'=>'inbox-vendor-id','address'=>'invalid'],[]);}catch(AmbiguousProvisioning){}eq(Wallet::balance($c['id'])['reserved_usd'],'1.00');$receipt=['id'=>'inbox-vendor-id','address'=>'inbox@example.invalid','expires_at'=>'2027-01-01 00:00:00'];query('UPDATE fulfilment_intents SET receipt=? WHERE id=?',[json_encode($receipt),$i]);Reconciliation::run($i);Reconciliation::run($i);eq(Wallet::balance($c['id'])['balance_usd'],'9.00');eq(Wallet::balance($c['id'])['reserved_usd'],'0.00');eq((int)one('SELECT COUNT(*) n FROM inboxes WHERE user_id=?',[$c['id']])['n'],1);});
test('Renewal receipt can be activated repeatedly but charges once',function(){ $c=customer('renewal@test.invalid');$o=seedOrder($c);query("UPDATE orders SET product='long-term',expires_at='2026-10-20 00:00:00' WHERE id=?",[$o]);$i=commerceIntent($c,'long-term',['id'=>$o],$o);$receipt=['id'=>'renewal-vendor-id','expires_at'=>'2026-11-20 00:00:00'];Commerce::activate($i,$receipt,['id'=>$o]);Commerce::activate($i,$receipt,['id'=>$o]);eq(Wallet::balance($c['id'])['balance_usd'],'9.00');eq((int)one("SELECT COUNT(*) n FROM ledger WHERE user_id=? AND kind='renewal'",[$c['id']])['n'],1);eq(Rentals::owned($o,$c['id'])['expires_at'],'2026-11-20 00:00:00');});
test('Uncertain provisioning is never released on unavailable lookup',function(){ $c=customer('uncertain@test.invalid');$i=commerceIntent($c,'temp-mail',[]);$before=Wallet::balance($c['id']);rejects(fn()=>Reconciliation::run($i),'PROVIDER_UNAVAILABLE');eq(Wallet::balance($c['id']),$before);});
test('Saved number receipt reconciles and captures only once',function(){ $c=customer('number-recovery@test.invalid');$o=seedOrder($c,'reconciliation');query('UPDATE orders SET provider_order_id=NULL WHERE id=?',[$o]);tx(function()use($c,$o){Wallet::change($c['id'],'topup',1000,'seed:'.$o,'Test funds');Wallet::change($c['id'],'reservation',0,'reserve:'.$o,'Test reserve',100);});query('INSERT INTO provider_receipts (intent_id,receipt,created_at) VALUES (?,?,?)',[$o,json_encode(['id'=>'provider-number-id','phone'=>'+12025550123','expires_at'=>'2027-01-01 00:00:00']),now()]);Reconciliation::run($o);Reconciliation::run($o);eq(Wallet::balance($c['id'])['balance_usd'],'9.00');eq(Rentals::owned($o,$c['id'])['status'],'active');});
foreach(['usa'=>'textverified','global'=>'5sim']as$product=>$source)test('Dashboard '.$product.' count includes active/completed only, including older completions',function()use($product,$source){
 $c=customer($product.'-counts@test.invalid');
 foreach(['active','completed','cancelled','expired','pending','reconciliation']as$status)seedOrder($c,$status,$source,$status==='completed'?'00123':null);
 $old=seedOrder($c,'completed',$source,'00123');query("UPDATE orders SET expires_at='2000-01-01 00:00:00' WHERE id=?",[$old]);
 $elapsed=seedOrder($c,'active',$source);query("UPDATE orders SET expires_at='2000-01-01 00:00:00' WHERE id=?",[$elapsed]);
 seedOrder(customer($product.'-other@test.invalid'),'active',$source);
 $list=Rentals::listing($c,$product,false,1,1);eq($list['total'],8);eq($list['active_completed_total'],3);eq(count($list['items']),1);
 eq(Rentals::listing($c,$product,true)['active_completed_total'],3);
});
echo "$passed passed; $failed failed\n";exit($failed?1:0);
